    // ─────────── فصل ۱: دستگیری ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Arrest", titlePersian = "دستگیری",
        paragraphs = listOf(
            StoryParagraph("Someone must have been telling lies about Josef K., for without having done anything wrong he was arrested one fine morning.", "کسی باید درباره یوزف ک. دروغ گفته باشد، زیرا بدون آنکه کار اشتباهی کرده باشد، یک صبح زیبا دستگیر شد."),
            StoryParagraph("His landlady's cook, who always brought him his breakfast at eight o'clock, failed to appear on this occasion.", "آشپز صاحب‌خانه‌اش که همیشه ساعت هشت صبحانه‌اش را می‌آورد، این بار نیامد."),
            StoryParagraph("That had never happened before.", "این هرگز قبلاً اتفاق نیفتاده بود."),
            StoryParagraph("K. waited for a little while longer, watching from his pillow the old lady opposite, who seemed to be peering at him with a curiosity unusual even for her.", "ک. کمی بیشتر منتظر ماند، از بالشش به پیرزنی روبه‌رو نگاه کرد که به نظر می‌رسید با کنجکاوی‌ای غیرعادی حتی برای او، به او خیره شده بود."),
            StoryParagraph("But then, feeling both hungry and offended, he rang the bell.", "اما بعد، که هم گرسنه بود و هم آزرده، زنگ زد."),
            StoryParagraph("Immediately there was a knock at the door, and a man he had never seen before in this house came in.", "بلافاصله در زده شد و مردی که هرگز قبلاً در این خانه ندیده بود وارد شد."),
            StoryParagraph("He was slim, yet firmly built, and was wearing a closely fitting black suit, which was arranged, as such suits are, with various pleats, pockets, buckles, and buttons, and which gave it, though it was clearly a travel outfit, an appearance of unusual practicality.", "لاغر بود اما محکم ساخته شده و کت و شلوار مشکی تنگی پوشیده بود که چون چنین کت و شلوارهایی چیده شده بود، با چین‌های مختلف، جیب‌ها، سگک‌ها و دکمه‌ها و ظاهری غیرعادی عملی به آن می‌داد، هرچند واضح بود لباس سفر است."),
            StoryParagraph("'Who are you?' asked K., sitting half upright in his bed.", "ک. که نیمه‌راست در تختش نشسته بود پرسید: «شما کی هستید؟»"),
            StoryParagraph("But the man ignored the question, as if his presence were something that needed no explanation.", "اما آن مرد پرسش را نادیده گرفت، گویی حضورش چیزی بود که نیازی به توضیح نداشت."),
            StoryParagraph("'You have been arrested,' the man said, at last, in a quiet, matter-of-fact voice.", "آن مرد سرانجام با صدایی آرام و خشک گفت: «شما دستگیر شده‌اید.»"),
            StoryParagraph("'But I don't know what crime I'm supposed to have committed,' said K., and he felt a strange mixture of irritation and curiosity.", "ک. گفت: «اما نمی‌دانم متهم به چه جنایتی شده‌ام.» و ترکیبی عجیب از آزردگی و کنجکاوی حس کرد."),
            StoryParagraph("'That is not for me to say,' said the man, and he opened the door to let in another man, a man named Franz, who stood at attention and looked at K. with a kind of blank expression.", "مرد گفت: «این را من نمی‌توانم بگویم.» و در را باز کرد تا مرد دیگری وارد شود، مردی به نام فرانتس که خبردار ایستاد و با نوعی حالت خالی به ک. نگاه کرد."),
            StoryParagraph("'You will be informed of the charges against you in due course,' said Franz. 'For now, you are required to remain in your room.'", "فرانتس گفت: «در زمان مقرر از اتهامات علیه شما مطلع خواهید شد. برای اکنون، باید در اتاقتان بمانید.»"),
            StoryParagraph("K. laughed, a short, bitter laugh, and he stood up from his bed.", "ک. خندید، خنده‌ای کوتاه و تلخ و از تختش بلند شد."),
            StoryParagraph("'I have no intention of remaining in my room,' he said. 'I have work to do. I am the chief clerk at a bank, and I have responsibilities.'", "گفت: «قصد ندارم در اتاقم بمانم. کار دارم. من رئیس دفتر یک بانک هستم و مسئولیت‌هایی دارم.»"),
            StoryParagraph("'That makes no difference,' said the man. 'You have been arrested.'", "مرد گفت: «این تفاوتی نمی‌کند. شما دستگیر شده‌اید.»"),
            StoryParagraph("And then K. understood, for the first time, that he was in a situation that he could not control, that he had no power over, that made no sense.", "و بعد ک. برای نخستین بار فهمید که در موقعیتی است که نمی‌تواند کنترلش کند، بر آن قدرتی ندارد، که هیچ معنایی ندارد."),
            StoryParagraph("'This is absurd,' he said, and his voice was raised. 'This is completely absurd. There must be some mistake.'", "گفت: «این پوچ است.» و صدایش بالا رفت. «این کاملاً پوچ است. باید اشتباهی باشد.»"),
            StoryParagraph("'There is no mistake,' said the man, and there was something in his voice that made K. believe him, something that made the situation even more terrible.", "مرد گفت: «اشتباهی نیست.» و چیزی در صدایش بود که ک. را وادار به باورش کرد، چیزی که موقعیت را حتی هولناک‌تر می‌کرد."),
            StoryParagraph("K. sat down on the edge of his bed, and he looked at the two men who had come to arrest him, and he tried to understand what was happening.", "ک. روی لبه تختش نشست و به دو مردی که آمده بودند دستگیرش کنند نگاه کرد و تلاش کرد بفهمد چه اتفاقی می‌افتد."),
            StoryParagraph("But he could not understand, and he knew that he would not understand, that there was nothing to understand.", "اما نمی‌توانست بفهمد و می‌دانست نمی‌فهمد، که چیزی برای فهمیدن نبود."),
            StoryParagraph("'Very well,' he said, at last. 'I will come with you. But I want it noted that I am coming of my own free will, and not because I acknowledge any guilt.'", "سرانجام گفت: «بسیار خوب. با شما می‌آیم. اما می‌خواهم ثبت شود که به اراده آزاد خودم می‌آیم، نه چون به هر گناهی اقرار می‌کنم.»"),
            StoryParagraph("'That will be noted,' said the man, but there was a slight smile on his face as he said it, and K. knew that nothing would be noted, that nothing mattered, that he was lost.", "مرد گفت: «این ثبت می‌شود.» اما وقتی این را می‌گفت لبخند خفیفی بر صورتش بود و ک. می‌دانست هیچ‌چیز ثبت نمی‌شود، هیچ‌چیز مهم نیست، که او گم شده است."),
            StoryParagraph("They led him into the next room, where a third man, a man named Willem, was waiting, and the three of them sat down at a table and looked at K. as if he were a specimen under a microscope.", "او را به اتاق بعدی بردند، جایی که مرد سومی به نام ویلم منتظر بود و هر سه‌شان پشت میزی نشستند و به ک. نگاه کردند گویی نمونه‌ای زیر میکروسکوپ است."),
            StoryParagraph("They asked him questions, questions about his life, his work, his family, his friends; but they did not ask him about any crime, and they did not tell him what he was accused of.", "از او سوال پرسیدند، سوال‌هایی درباره زندگی‌اش، کارش، خانواده‌اش، دوستانش؛ اما درباره هیچ جنایتی نپرسیدند و نگفتند متهم به چیست."),
            StoryParagraph("K. answered the questions, one by one, and he tried to be patient, and he tried to understand; but each answer led only to another question, and each question led only to confusion.", "ک. یکی‌یکی به سوال‌ها پاسخ داد و تلاش کرد صبور باشد و تلاش کرد بفهمد؛ اما هر پاسخ تنها به سوال دیگری می‌رسید و هر سوال تنها به گیجی."),
            StoryParagraph("'This is absurd,' he said again, and this time there was despair in his voice.", "دوباره گفت: «این پوچ است.» و این بار در صدایش ناامیدی بود."),
            StoryParagraph("'Yes,' said one of the men, 'it is absurd. But that does not make it any less real.'", "یکی از مردان گفت: «بله، پوچ است. اما این واقعی بودنش را کمتر نمی‌کند.»"),
            StoryParagraph("And then they let him go, and K. walked out of his room, out of his house, into the street, where the sun was shining and the world was going on as if nothing had happened.", "و بعد رهایش کردند و ک. از اتاقش بیرون رفت، از خانه‌اش، به خیابان، جایی که خورشید می‌تابید و جهان ادامه داشت گویی هیچ اتفاقی نیفتاده."),
            StoryParagraph("But something had happened, something that K. did not understand, something that would haunt him for the rest of his life.", "اما اتفاقی افتاده بود، چیزی که ک. نمی‌فهمید، چیزی که باقی عمرش تسخیرش می‌کرد."),
            StoryParagraph("He went to his office, and he tried to work, and he tried to pretend that everything was normal.", "به دفترش رفت و تلاش کرد کار کند و تلاش کرد تظاهر کند همه چیز عادی است."),
            StoryParagraph("But nothing was normal, and he knew it, and he could not pretend otherwise.", "اما هیچ چیز عادی نبود و می‌دانست و نمی‌توانست خلافش را تظاهر کند."),
            StoryParagraph("For he had been arrested, and he did not know why, and he would never know why.", "زیرا دستگیر شده بود و نمی‌دانست چرا و هرگز نمی‌دانست چرا."),
            StoryParagraph("And in that not-knowing, in that absurdity, in that meaninglessness, was a truth about the world that K. had never suspected.", "و در آن ندانستن، در آن پوچی، در آن بی‌معنایی، حقیقتی درباره جهان بود که ک. هرگز گمانش را نمی‌برد."),
            StoryParagraph("It was the truth that the world does not make sense, that justice is not always done, that the innocent can be punished as easily as the guilty.", "این حقیقت بود که جهان معنا ندارد، که عدالت همیشه اجرا نمی‌شود، که بی‌گناه به همان راحتی گناهکار می‌تواند مجازات شود."),
            StoryParagraph("And K., who had lived his whole life as a respectable man, who had believed in order and reason and justice, would have to learn this truth.", "و ک.، که تمام عمرش را به‌عنوان مردی محترم زیسته بود، که به نظم و عقل و عدالت باور داشت، باید این حقیقت را می‌آموخت."),
            StoryParagraph("He would learn it slowly, painfully, and completely, until there was nothing left of his old self.", "آن را به‌آرامی می‌آموخت، به‌دردناکی و کاملاً، تا هیچ‌چیز از خودِ قبلی‌اش باقی نمی‌ماند."),
            StoryParagraph("And so began the trial of Josef K., a trial that had no end, that had no meaning, that would consume him entirely.", "و اینگونه محاکمه یوزف ک. آغاز شد، محاکمه‌ای که پایانی نداشت، معنایی نداشت، که تمامش را می‌خورد."),
            StoryParagraph("He did not know it yet, but his life had already ended; the rest was just the long, slow dying.", "هنوز نمی‌دانست، اما زندگی‌اش از قبل تمام شده بود؛ باقی فقط مردن طولانی و آهسته بود.")
        )
    )

    // ─────────── فصل ۲: بازجویی ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "The Interrogation", titlePersian = "بازجویی",
        paragraphs = listOf(
            StoryParagraph("A few days later, K. received a telephone call at his office telling him to appear for interrogation on Sunday morning at a certain address in the suburbs.", "چند روز بعد، ک. تماسی تلفنی در دفترش دریافت کرد که به او می‌گفت صبح یکشنبه در آدرسی در حاشیه شهر برای بازجویی حاضر شود."),
            StoryParagraph("He was not told what the interrogation was about, nor who would conduct it, nor what he was expected to say.", "به او گفته نشد بازجویی درباره چیست، نه چه کسی انجامش می‌دهد، نه از او انتظار می‌رود چه بگوید."),
            StoryParagraph("He simply had to be there, at that time, at that place, and that was all.", "تنها باید آنجا می‌بود، در آن زمان، در آن مکان و همین."),
            StoryParagraph("K. was annoyed, but he was also curious; he wanted to know what was happening to him, why he had been arrested, what he was accused of.", "ک. آزرده بود اما کنجکاو هم بود؛ می‌خواست بداند چه بر سرش می‌آید، چرا دستگیر شده، متهم به چیست."),
            StoryParagraph("So on Sunday morning, he made his way to the address he had been given, which turned out to be a large, dilapidated apartment building in a poor part of town.", "پس صبح یکشنبه راهی آدرسی شد که به او داده بودند که معلوم شد ساختمانی بزرگ و مخروبه در بخش فقیرنشین شهر است."),
            StoryParagraph("He found the room where the interrogation was to take place, and he entered, and he found himself in a large hall, filled with people.", "اتاقی که بازجویی در آن برگزار می‌شد را پیدا کرد و وارد شد و خود را در سالنی بزرگ یافت، پر از مردم."),
            StoryParagraph("The people were of all kinds — old and young, men and women, rich and poor — and they all seemed to be waiting for something.", "مردم از همه نوع بودند — پیر و جوان، مرد و زن، ثروتمند و فقیر — و همه به نظر می‌رسید منتظر چیزی هستند."),
            StoryParagraph("K. was told to sit down on a bench, and he did, and he waited, and he watched.", "به ک. گفتند روی نیمکتی بنشیند و او نشست و منتظر ماند و تماشا کرد."),
            StoryParagraph("After a long time, a man appeared at the front of the hall and called K.'s name.", "پس از مدت طولانی، مردی در جلوی سالن ظاهر شد و نام ک. را صدا زد."),
            StoryParagraph("K. stood up and walked to the front, where he was told to stand on a small platform, in full view of everyone.", "ک. بلند شد و به جلو رفت، جایی که به او گفتند روی سکوی کوچکی بایستد، در دید کامل همه."),
            StoryParagraph("'You are Josef K.?' the man asked, though he clearly knew the answer.", "مرد پرسید: «شما یوزف ک. هستید؟» هرچند واضح بود پاسخ را می‌دانست."),
            StoryParagraph("'Yes,' said K.", "ک. گفت: «بله.»"),
            StoryParagraph("'You are accused of a serious crime,' said the man. 'What do you have to say for yourself?'", "مرد گفت: «شما به جنایت جدی‌ای متهم هستید. چه چیزی برای دفاع از خودتان دارید؟»"),
            StoryParagraph("'I do not know what crime I am accused of,' said K. 'I have not been told. I do not know what this is about.'", "ک. گفت: «نمی‌دانم به چه جنایتی متهمم. به من نگفته‌اند. نمی‌دانم این درباره چیست.»"),
            StoryParagraph("'That is irrelevant,' said the man. 'You are accused. That is enough.'", "مرد گفت: «این بی‌ربط است. شما متهمید. همین کافی است.»"),
            StoryParagraph("K. felt a wave of anger rise in him, but he controlled it, and he spoke calmly.", "ک. موجی از خشم در خود حس کرد اما کنترلش کرد و آرام صحبت کرد."),
            StoryParagraph("'I demand to know what I am accused of,' he said. 'I demand to see the charges against me. I demand to speak to a lawyer.'", "گفت: «تقاضا می‌کنم بدانم متهم به چه هستم. تقاضا می‌کنم اتهامات علیه خودم را ببینم. تقاضا می‌کنم با وکیلی صحبت کنم.»"),
            StoryParagraph("'There are no charges to see,' said the man. 'There is no lawyer to speak to. There is only the trial, and the trial has begun.'", "مرد گفت: «اتهامی برای دیدن نیست. وکیلی برای صحبت کردن نیست. تنها محاکمه هست و محاکمه آغاز شده.»"),
            StoryParagraph("And then K. understood, with a clarity that was almost painful, that he was not dealing with any ordinary system of justice.", "و بعد ک. با وضوحی که تقریباً دردناک بود فهمید که با هیچ نظام عدالت معمولی سر و کار ندارد."),
            StoryParagraph("He was dealing with something else, something older, something darker, something that had no rules and no reason.", "با چیز دیگری سر و کار داشت، چیزی کهن‌تر، تاریک‌تر، چیزی که هیچ قاعده و دلیلی نداشت."),
            StoryParagraph("'I refuse to participate in this,' he said, and he stepped down from the platform.", "گفت: «از شرکت در این امتناع می‌کنم.» و از سکو پایین آمد."),
            StoryParagraph("'You cannot refuse,' said the man. 'The trial will continue, whether you participate or not.'", "مرد گفت: «نمی‌توانید امتناع کنید. محاکمه ادامه می‌یابد، چه شرکت کنید چه نکنید.»"),
            StoryParagraph("K. walked out of the hall, and he walked out of the building, and he walked out into the street.", "ک. از سالن بیرون رفت و از ساختمان و به خیابان."),
            StoryParagraph("He felt, for a moment, a sense of triumph, of having escaped, of having refused to be caught in their trap.", "برای لحظه‌ای حسی از پیروزی حس کرد، از فرار کرده، از امتناع از گرفتار شدن در تله‌شان."),
            StoryParagraph("But the feeling did not last; it was replaced by a deeper unease, a sense that he had accomplished nothing, that he was still caught, that there was no escape.", "اما این حس دوام نیاورد؛ جایگزین شد با ناآرامی عمیق‌تری، حسی که هیچ کاری نکرده، که هنوز گرفتار است، که گریزی نیست."),
            StoryParagraph("He went back to his apartment, and he tried to resume his normal life, but he found that he could not.", "به آپارتمانش بازگشت و تلاش کرد زندگی عادی‌اش را از سر بگیرد اما یافت که نمی‌تواند."),
            StoryParagraph("Everything seemed different now; everything seemed unreal; everything seemed part of a dream from which he could not wake.", "حالا همه چیز متفاوت به نظر می‌رسید؛ همه چیز غیرواقعی؛ همه چیز بخشی از رؤیایی که نمی‌توانست از آن بیدار شود."),
            StoryParagraph("He went to his office, and he did his work, but his mind was elsewhere.", "به دفترش رفت و کارش را کرد اما ذهنش جای دیگری بود."),
            StoryParagraph("He saw his friends, and he talked to them, but he could not tell them what was happening to him.", "دوستانش را دید و با آن‌ها صحبت کرد اما نمی‌توانست به آن‌ها بگوید چه بر سرش می‌آید."),
            StoryParagraph("For how could he explain something he did not understand himself?", "زیرا چطور می‌توانست چیزی را توضیح دهد که خودش نمی‌فهمید؟"),
            StoryParagraph("He began to feel that he was alone in the world, alone with his trial, alone with his guilt — a guilt he did not understand and could not deny.", "شروع کرد به حس کردن که در جهان تنهاست، تنها با محاکمه‌اش، تنها با گناهش — گناهی که نمی‌فهمید و نمی‌توانست انکارش کند."),
            StoryParagraph("For the more he denied his guilt, the more guilty he felt; the more he protested his innocence, the less innocent he seemed.", "زیرا هرچه بیشتر گناهش را انکار می‌کرد، بیشتر گناهکار حس می‌کرد؛ هرچه بیشتر بی‌گناهی‌اش را اعتراض می‌کرد، کمتر بی‌گناه به نظر می‌رسید."),
            StoryParagraph("And so he began to wonder, for the first time in his life, whether he really was guilty, whether there was some crime he had committed without knowing it, some sin for which he must atone.", "و اینگونه شروع کرد به حیرت کردن، برای نخستین بار در زندگی‌اش، که آیا واقعاً گناهکار است، آیا جنایتی هست که بدون دانستنش مرتکب شده، گناهی که باید برایش کفاره بدهد."),
            StoryParagraph("But he could think of nothing, no crime, no sin; his life had been ordinary, respectable, blameless.", "اما نمی‌توانست چیزی به ذهن بیاورد، نه جنایتی، نه گناهی؛ زندگی‌اش عادی بود، محترم، بی‌عیب."),
            StoryParagraph("And yet, the trial continued, and the accusation stood, and K. began to feel that perhaps the trial was not about a crime at all.", "و با این حال، محاکمه ادامه یافت و اتهام باقی ماند و ک. شروع کرد به حس کردن که شاید محاکمه اصلاً درباره جنایت نیست."),
            StoryParagraph("Perhaps it was about something else, something deeper, something that could not be named.", "شاید درباره چیز دیگری است، چیزی عمیق‌تر، چیزی که نمی‌شد نامید."),
            StoryParagraph("Perhaps it was about the fact of being alive, of being human, of being part of a world that made no sense.", "شاید درباره خودِ زنده بودن است، انسان بودن، بخشی از جهانی بودن که معنایی ندارد."),
            StoryParagraph("And K., who had lived his whole life as a man of reason, found himself in a world without reason, a world where the innocent were guilty and the guilty were innocent.", "و ک.، که تمام عمرش را به‌عنوان مردی عقلانی زیسته بود، خود را در جهانی بی‌عقل یافت، جهانی که در آن بی‌گناه گناهکار است و گناهکار بی‌گناه."),
            StoryParagraph("It was a world he did not understand, but it was the world he lived in, and he could not escape from it.", "جهانی بود که نمی‌فهمید، اما جهانی بود که در آن زندگی می‌کرد و نمی‌توانست از آن بگریزد."),
            StoryParagraph("So he waited, and he watched, and he wondered what would happen next.", "پس منتظر ماند و تماشا کرد و حیران شد بعد چه اتفاقی می‌افتد."),
            StoryParagraph("And what happened next was that the trial continued, as it would continue for many months, for a year, for the rest of his life.", "و آنچه بعد اتفاق افتاد این بود که محاکمه ادامه یافت، همانطور که ماه‌ها ادامه می‌یافت، یک سال، باقی عمرش.")
        )
    )

    // ─────────── فصل ۳: عمو ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "The Uncle", titlePersian = "عمو",
        paragraphs = listOf(
            StoryParagraph("One day, K. received a visit from his uncle, a man named Karl, who had heard something of the trial and had come to help.", "یک روز، ک. ملاقاتی از عمویش دریافت کرد، مردی به نام کارل که چیزی از محاکمه شنیده بود و آمده بود کمک کند."),
            StoryParagraph("Uncle Karl was a country gentleman, a man of some influence, a man who believed in the importance of family.", "عمو کارل جنتلمنی روستایی بود، مردی با نفوذی، مردی که به اهمیت خانواده باور داشت."),
            StoryParagraph("'Josef,' he said, 'this is a serious matter. You must take it seriously.'", "گفت: «یوزف، این موضوع جدی است. باید جدی بگیری‌اش.»"),
            StoryParagraph("'I do take it seriously,' said K. 'But there is nothing I can do. I do not even know what I am accused of.'", "ک. گفت: «جدی می‌گیرمش. اما کاری نمی‌توانم بکنم. حتی نمی‌دانم متهم به چه هستم.»"),
            StoryParagraph("'That is what worries me,' said Uncle Karl. 'You must have a lawyer. I know a lawyer, a man named Huld, who has experience with these matters.'", "عمو کارل گفت: «همین نگرانم می‌کند. باید وکیلی داشته باشی. وکیلی می‌شناسم، مردی به نام هولد که در این مسائل تجربه دارد.»"),
            StoryParagraph("And so, the next day, K. and his uncle went to see the lawyer, Dr. Huld, who lived in a large, dark house on a quiet street.", "و اینگونه، روز بعد، ک. و عمویش به دیدن وکیل رفتند، دکتر هولد که در خانه‌ای بزرگ و تاریک در خیابانی آرام زندگی می‌کرد."),
            StoryParagraph("Dr. Huld was an old man, sick and bedridden, but his mind was sharp, and his voice was commanding.", "دکتر هولد پیرمردی بود، بیمار و بستری اما ذهنش تیز بود و صدایش فرمانده."),
            StoryParagraph("'So,' he said, after K. had explained his situation, 'you have been arrested, and you do not know why.'", "او پس از اینکه ک. وضعیتش را توضیح داد گفت: «پس، دستگیر شده‌اید و نمی‌دانید چرا.»"),
            StoryParagraph("'That is correct,' said K.", "ک. گفت: «درست است.»"),
            StoryParagraph("'And you want me to defend you,' said Dr. Huld. 'But defend you against what?'", "دکتر هولد گفت: «و می‌خواهید از شما دفاع کنم. اما در برابر چه؟»"),
            StoryParagraph("'That is what I do not know,' said K. 'That is what I am trying to find out.'", "ک. گفت: «این را نمی‌دانم. این را تلاش می‌کنم کشف کنم.»"),
            StoryParagraph("'The court,' said Dr. Huld, 'does not work the way you think. It is not a court of law. It is not a court of justice. It is something else entirely.'", "دکتر هولد گفت: «دادگاه آن‌طور که فکر می‌کنید کار نمی‌کند. دادگاه قانون نیست. دادگاه عدالت نیست. چیز کاملاً دیگری است.»"),
            StoryParagraph("'What is it, then?' asked K.", "ک. پرسید: «پس چیست؟»"),
            StoryParagraph("'It is a machine,' said Dr. Huld. 'A vast, ancient machine that grinds everything that comes into contact with it. No one knows who built it, or why, or what its purpose is. It simply is.'", "دکتر هولد گفت: «ماشینی است. ماشینی عظیم و کهن که هر چیزی را که با آن تماس پیدا کند خرد می‌کند. هیچ‌کس نمی‌داند چه کسی ساخته، چرا، یا هدفش چیست. تنها هست.»"),
            StoryParagraph("'And what can be done?' asked K.", "ک. پرسید: «و چه می‌شود کرد؟»"),
            StoryParagraph("'Nothing,' said Dr. Huld. 'Nothing can be done. The only thing to do is to survive as long as possible, to delay the process, to keep the machine from grinding you up.'", "دکتر هولد گفت: «هیچ. هیچ کاری نمی‌شود کرد. تنها کاری که باید کرد این است که تا جای ممکن زنده بمانی، روند را به تأخیر بیندازی، نگذاری ماشین خردت کند.»"),
            StoryParagraph("'That is not acceptable,' said K. 'I refuse to accept that.'", "ک. گفت: «این قابل قبول نیست. از پذیرشش امتناع می‌کنم.»"),
            StoryParagraph("'Your refusal,' said Dr. Huld, 'means nothing to the machine. The machine does not care whether you accept it or not.'", "دکتر هولد گفت: «امتناع تو برای ماشین هیچ معنایی ندارد. ماشین اهمیتی نمی‌دهد قبول کنی یا نه.»"),
            StoryParagraph("Uncle Karl, who had been listening in silence, spoke up.", "عمو کارل که در سکوت گوش می‌داد سخن گفت."),
            StoryParagraph("'But there must be something we can do,' he said. 'There must be a way to help my nephew.'", "گفت: «اما باید کاری باشد که بتوانیم بکنیم. باید راهی برای کمک به برادرزاده‌ام باشد.»"),
            StoryParagraph("'There is a way,' said Dr. Huld, 'but it is not a way you will like. It is a way of submission, of compromise, of playing the machine's game.'", "دکتر هولد گفت: «راهی هست، اما راهی نیست که دوست داشته باشید. راهی است از تسلیم، از سازش، از بازی کردن بازی ماشین.»"),
            StoryParagraph("'What do you mean?' asked K.", "ک. پرسید: «منظورتان چیست؟»"),
            StoryParagraph("'You must write petitions,' said Dr. Huld. 'You must hire advocates. You must attend hearings. You must do everything the machine asks of you, all the while knowing that none of it will help.'", "دکتر هولد گفت: «باید عریضه بنویسید. باید وکیل استخدام کنید. باید در جلسات حاضر شوید. باید هر کاری که ماشین از شما می‌خواهد بکنید، در حالی که می‌دانید هیچ‌کدام کمکی نمی‌کند.»"),
            StoryParagraph("'That is madness,' said K. 'That is doing nothing while pretending to do something.'", "ک. گفت: «این جنون است. این هیچ کاری نکردن است در حالی که تظاهر می‌کنی کاری می‌کنی.»"),
            StoryParagraph("'Yes,' said Dr. Huld. 'That is exactly what it is. Welcome to the court.'", "دکتر هولد گفت: «بله. این دقیقاً همان است. به دادگاه خوش آمدید.»"),
            StoryParagraph("K. left the lawyer's house in despair; he had hoped for help, for guidance, for some way out of his situation, and he had found only more confusion, more darkness, more despair.", "ک. با ناامیدی از خانه وکیل بیرون رفت؛ به کمک امید داشت، به راهنمایی، به راهی برای خروج از موقعیتش و تنها گیجی بیشتر یافته بود، تاریکی بیشتر، ناامیدی بیشتر."),
            StoryParagraph("Uncle Karl tried to comfort him, but K. would not be comforted; he knew now that he was alone, truly alone, more alone than he had ever been.", "عمو کارل تلاش کرد دلداری‌اش دهد اما ک. دلداری نمی‌پذیرفت؛ حالا می‌دانست که تنهاست، واقعاً تنها، تنهاتر از آنچه تا به حال بوده."),
            StoryParagraph("'What will you do?' asked Uncle Karl.", "عمو کارل پرسید: «چه می‌کنی؟»"),
            StoryParagraph("'I will fight,' said K. 'I will fight this court, this machine, this absurdity. I will not submit.'", "ک. گفت: «می‌جنگم. با این دادگاه، این ماشین، این پوچی می‌جنگم. تسلیم نمی‌شوم.»"),
            StoryParagraph("'And if you lose?' asked Uncle Karl.", "عمو کارل پرسید: «و اگر ببازی؟»"),
            StoryParagraph("'Then I will lose,' said K. 'But at least I will have fought.'", "ک. گفت: «پس می‌بازم. اما دست‌کم جنگیده‌ام.»"),
            StoryParagraph("But even as he said it, he knew that his words were empty, that fighting was useless, that the machine would grind him up no matter what he did.", "اما حتی همانطور که می‌گفت، می‌دانست کلماتش توخالی‌اند، که جنگیدن بی‌فایده است، که ماشین خردش می‌کند هر چه بکند."),
            StoryParagraph("And in that knowledge, in that despair, K. began to lose himself, to lose his sense of who he was, to lose the certainty that had sustained him all his life.", "و در آن دانش، در آن ناامیدی، ک. شروع کرد به گم کردن خودش، به گم کردن حس اینکه کیست، به گم کردن یقینی که تمام عمرش نگهش داشته بود."),
            StoryParagraph("He had always known who he was: a respectable man, a chief clerk at a bank, a man of order and reason.", "همیشه می‌دانست کیست: مردی محترم، رئیس دفتر بانکی، مردی از نظم و عقل."),
            StoryParagraph("But now he did not know, could not know, would never know again.", "اما حالا نمی‌دانست، نمی‌توانست بداند، هرگز دیگر نمی‌دانست."),
            StoryParagraph("The trial had taken that from him, had taken everything from him, and would continue to take until there was nothing left.", "محاکمه آن را از او گرفته بود، همه چیز را از او گرفته بود و به گرفتن ادامه می‌داد تا چیزی باقی نماند."),
            StoryParagraph("And K., walking home alone through the dark streets, felt for the first time in his life that he was truly lost.", "و ک.، در حال قدم زدن تنها در خیابان‌های تاریک به خانه، برای نخستین بار در زندگی‌اش حس کرد که واقعاً گم شده است.")
        )
    )

    // ─────────── فصل ۴: در کلیسا ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "In the Cathedral", titlePersian = "در کلیسا",
        paragraphs = listOf(
            StoryParagraph("Months passed, and the trial continued, and K. grew more and more weary of it.", "ماه‌ها گذشت و محاکمه ادامه یافت و ک. بیشتر و بیشتر از آن خسته شد."),
            StoryParagraph("He had written petitions, he had hired advocates, he had attended hearings; but nothing had changed, nothing had progressed.", "عریضه نوشته بود، وکیل استخدام کرده بود، در جلسات حاضر شده بود؛ اما هیچ چیز تغییر نکرده بود، هیچ چیز پیش نرفته بود."),
            StoryParagraph("The trial was like a disease, a slow, wasting disease that consumed him from within, that left him hollow and empty.", "محاکمه مثل بیماری بود، بیماری‌ای کند و فرساینده که از درونش می‌خورد، توخالی و تهی رهایش می‌کرد."),
            StoryParagraph("One day, K. was asked to come to the cathedral to show a visiting Italian businessman around.", "یک روز، از ک. خواسته شد به کلیسا بیاید تا به تاجری ایتالیایی که بازدید می‌کرد شهر را نشان دهد."),
            StoryParagraph("K. agreed, though he did not know why the bank had chosen him, and he did not really care.", "ک. موافقت کرد، هرچند نمی‌دانست چرا بانک او را انتخاب کرده و واقعاً اهمیتی نمی‌داد."),
            StoryParagraph("He went to the cathedral, and he found it dark and empty, and he waited for the Italian, who did not come.", "به کلیسا رفت و تاریک و خالی یافتش و منتظر ایتالیایی ماند که نیامد."),
            StoryParagraph("The cathedral was vast and silent, filled with shadows and echoes, and K. felt small and insignificant in its presence.", "کلیسا عظیم و ساکت بود، پر از سایه‌ها و پژواک‌ها و ک. در حضورش کوچک و ناچیز حس کرد."),
            StoryParagraph("He walked among the columns, looking at the paintings and the statues, and he thought about his trial.", "میان ستون‌ها قدم زد، به نقاشی‌ها و مجسمه‌ها نگاه کرد و به محاکمه‌اش فکر کرد."),
            StoryParagraph("He thought about the absurdity of it all, about the meaninglessness, about the injustice.", "به پوچی همه‌اش فکر کرد، به بی‌معنایی، به بی‌عدالتی."),
            StoryParagraph("And then, suddenly, a voice called out his name.", "و بعد، ناگهان، صدایی نامش را صدا زد."),
            StoryParagraph("'Josef K.!' the voice said, and K. turned to see a priest standing in a pulpit above him.", "صدا گفت: «یوزف ک.!» و ک. برگشت و کشیشی را دید که در منبری بالای سرش ایستاده."),
            StoryParagraph("The priest was old, and his face was kind, and his voice was gentle but firm.", "کشیش پیر بود و چهره‌اش مهربان و صدایش لطیف اما محکم."),
            StoryParagraph("'You are late,' said the priest. 'I have been waiting for you.'", "کشیش گفت: «دیر کرده‌اید. منتظرتان بوده‌ام.»"),
            StoryParagraph("'I was told to come here,' said K. 'But I do not know why.'", "ک. گفت: «به من گفتند اینجا بیایم. اما نمی‌دانم چرا.»"),
            StoryParagraph("'You are here because your trial is here,' said the priest. 'Your trial is everywhere. It is not confined to any courtroom.'", "کشیش گفت: «اینجا هستید چون محاکمه‌تان اینجاست. محاکمه‌تان همه‌جاست. به هیچ دادگاهی محدود نیست.»"),
            StoryParagraph("'Do you know about my trial?' asked K.", "ک. پرسید: «از محاکمه‌ام می‌دانید؟»"),
            StoryParagraph("'I know about all trials,' said the priest. 'I know that yours is not going well. I know that you are losing hope.'", "کشیش گفت: «از همه محاکمه‌ها می‌دانم. می‌دانم محاکمه شما خوب پیش نمی‌رود. می‌دانم امیدتان را از دست می‌دهید.»"),
            StoryParagraph("'What can I do?' asked K. 'How can I win?'", "ک. پرسید: «چه می‌توانم بکنم؟ چطور می‌توانم ببرم؟»"),
            StoryParagraph("'You cannot win,' said the priest. 'The court does not lose. The court is not a game. It is a fact.'", "کشیش گفت: «نمی‌توانید ببرید. دادگاه نمی‌بازد. دادگاه بازی نیست. واقعیت است.»"),
            StoryParagraph("'Then what is the point?' cried K. 'Why go on? Why fight?'", "ک. فریاد زد: «پس فایده‌اش چیست؟ چرا ادامه دادن؟ چرا جنگیدن؟»"),
            StoryParagraph("'There is no point,' said the priest. 'There is no reason. There is only what is. And what is, is that you are on trial, and the trial will continue, and you will be judged.'", "کشیش گفت: «فایده‌ای نیست. دلیلی نیست. تنها آنچه هست، هست. و آنچه هست این است که شما در محاکمه‌اید و محاکمه ادامه می‌یابد و داوری می‌شوید.»"),
            StoryParagraph("'Judged by whom?' asked K. 'By what authority?'", "ک. پرسید: «توسط چه کسی داوری می‌شوم؟ به چه اختیاری؟»"),
            StoryParagraph("'By the court,' said the priest. 'The court has its own authority. It does not need to justify itself.'", "کشیش گفت: «توسط دادگاه. دادگاه اختیار خودش را دارد. نیازی به توجیه خودش ندارد.»"),
            StoryParagraph("'That is tyranny,' said K. 'That is not justice.'", "ک. گفت: «این استبداد است. این عدالت نیست.»"),
            StoryParagraph("'Perhaps,' said the priest. 'But it is the world we live in. And you must learn to live in it.'", "کشیش گفت: «شاید. اما این جهانی است که در آن زندگی می‌کنیم. و باید یاد بگیری در آن زندگی کنی.»"),
            StoryParagraph("'I will not accept it,' said K. 'I will not accept injustice.'", "ک. گفت: «قبولش نمی‌کنم. بی‌عدالتی را قبول نمی‌کنم.»"),
            StoryParagraph("'Then you will be destroyed,' said the priest. 'Not by the court, but by your own refusal to accept.'", "کشیش گفت: «پس نابود می‌شوید. نه توسط دادگاه، بلکه توسط امتناع خودتان از پذیرش.»"),
            StoryParagraph("The priest told K. a story, a parable about a man who came to the door of the law and waited his whole life to be admitted, and who was never admitted, and who died waiting.", "کشیش برای ک. داستانی تعریف کرد، مَثَلی درباره مردی که به در قانون آمد و تمام عمرش منتظر ماند تا وارد شود و هرگز وارد نشد و در انتظار مرد."),
            StoryParagraph("'What does the story mean?' asked K.", "ک. پرسید: «داستان چه معنایی دارد؟»"),
            StoryParagraph("'It means,' said the priest, 'that the law is always there, waiting for us, but that we can never enter it. It means that we are always outside, always excluded, always waiting.'", "کشیش گفت: «معنایش این است که قانون همیشه آنجاست، منتظر ما، اما ما هرگز نمی‌توانیم واردش شویم. معنایش این است که ما همیشه بیرونیم، همیشه طردشده، همیشه منتظر.»"),
            StoryParagraph("'That is the most terrible thing I have ever heard,' said K.", "ک. گفت: «این هولناک‌ترین چیزی است که تا حالا شنیده‌ام.»"),
            StoryParagraph("'Yes,' said the priest. 'It is. And yet it is the truth. And the truth, however terrible, is better than a comfortable lie.'", "کشیش گفت: «بله. هست. و با این حال حقیقت است. و حقیقت، هر چقدر هولناک، از دروغی راحت بهتر است.»"),
            StoryParagraph("K. left the cathedral in a state of despair; he had hoped for comfort, for guidance, for some way out of his situation, and he had found only more darkness.", "ک. با حالتی از ناامیدی کلیسا را ترک کرد؛ به تسلی امید داشت، به راهنمایی، به راهی برای خروج از موقعیتش و تنها تاریکی بیشتری یافته بود."),
            StoryParagraph("He walked home through the empty streets, and he thought about what the priest had said.", "در خیابان‌های خالی به خانه رفت و به آنچه کشیش گفته بود فکر کرد."),
            StoryParagraph("The law was always there, waiting for him, but he could never enter it.", "قانون همیشه آنجا بود، منتظرش، اما او هرگز نمی‌توانست واردش شود."),
            StoryParagraph("He was always outside, always excluded, always waiting.", "او همیشه بیرون بود، همیشه طردشده، همیشه منتظر."),
            StoryParagraph("And in that waiting, in that exclusion, in that impossibility, was the truth about his life, about all lives, about the human condition.", "و در آن انتظار، در آن طرد، در آن ناممکنی، حقیقت درباره زندگی‌اش بود، درباره همه زندگی‌ها، درباره وضعیت بشری."),
            StoryParagraph("K. understood this now, and the understanding filled him with a peace that was also a despair.", "ک. حالا این را می‌فهمید و این فهم او را پر از آرامشی می‌کرد که ناامیدی هم بود."),
            StoryParagraph("He had been fighting a battle he could not win, against an enemy he could not see, for a cause he could not name.", "با نبردی می‌جنگید که نمی‌توانست ببرد، علیه دشمنی که نمی‌توانست ببیند، برای آرمانی که نمی‌توانست نامش را ببرد."),
            StoryParagraph("And in the end, all he could do was accept, and wait, and see what would come.", "و در پایان، تنها می‌توانست بپذیرد و منتظر بماند و ببیند چه می‌آید.")
        )
    )

    // ─────────── فصل ۵: اعدام ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Execution", titlePersian = "اعدام",
        paragraphs = listOf(
            StoryParagraph("The evening before his thirty-first birthday, K. was sitting in his room, alone, waiting.", "شب پیش از سی و یکمین سالگرد تولدش، ک. در اتاقش نشسته بود، تنها، منتظر."),
            StoryParagraph("He did not know what he was waiting for, but he knew that something was coming, that something had to come.", "نمی‌دانست منتظر چه است، اما می‌دانست چیزی می‌آید، که چیزی باید بیاید."),
            StoryParagraph("The trial had gone on for a year, and it had consumed everything, and now it was about to end.", "محاکمه یک سال ادامه یافته بود و همه چیز را خورده بود و حالا در شرف پایان بود."),
            StoryParagraph("Two men arrived at his door, men he had never seen before, men dressed in black, men with cold, expressionless faces.", "دو مرد به در خانه‌اش رسیدند، مردانی که هرگز ندیده بود، مردانی سیاه‌پوش، مردانی با چهره‌های سرد و بی‌بیان."),
            StoryParagraph("'You are to come with us,' one of them said.", "یکی از آن‌ها گفت: «با ما می‌آیید.»"),
            StoryParagraph("K. did not resist; he had known this moment would come, had expected it, had perhaps even wanted it.", "ک. مقاومت نکرد؛ می‌دانست این لحظه می‌آید، انتظارش را داشت، شاید حتی می‌خواستش."),
            StoryParagraph("He put on his coat, and he followed the two men out into the street.", "پالتوش را پوشید و دنبال دو مرد به خیابان رفت."),
            StoryParagraph("It was a dark night, and the streets were empty, and no one saw them as they walked.", "شبی تاریک بود و خیابان‌ها خالی و هیچ‌کس ندیدشان همانطور که راه می‌رفتند."),
            StoryParagraph("They walked for a long time, past buildings K. recognized and buildings he did not, past squares and alleys and abandoned lots.", "مدت طولانی راه رفتند، از کنار ساختمان‌هایی که ک. می‌شناخت و ساختمان‌هایی که نمی‌شناخت، از کنار میدان‌ها و کوچه‌ها و زمین‌های خالی."),
            StoryParagraph("Eventually, they came to a small quarry on the edge of the city, a place of rocks and rubble, a place of desolation and silence.", "سرانجام، به معدن سنگی کوچکی در حاشیه شهر رسیدند، جایی از سنگ‌ها و آوار، جایی از ویرانی و سکوت."),
            StoryParagraph("'This is where it ends,' said one of the men.", "یکی از آن‌ها گفت: «اینجا جایی است که تمام می‌شود.»"),
            StoryParagraph("K. understood what was going to happen, and he did not try to escape, and he did not beg for his life.", "ک. فهمید چه اتفاقی می‌افتد و تلاش نکرد فرار کند و التماس نکرد برای زندگی‌اش."),
            StoryParagraph("He had known, for a long time, that this was coming, that there was no other ending possible, that the trial could only end in death.", "مدت‌ها می‌دانست که این می‌آید، که هیچ پایان دیگری ممکن نیست، که محاکمه تنها می‌تواند به مرگ ختم شود."),
            StoryParagraph("But even in that knowledge, even in that acceptance, there was a question that would not leave him.", "اما حتی در آن دانش، حتی در آن پذیرش، پرسشی بود که رهایش نمی‌کرد."),
            StoryParagraph("Where was the judge? Where was the court? Where was the sentence that had condemned him?", "قاضی کجا بود؟ دادگاه کجا بود؟ حکمی که محکومش کرده بود کجا بود؟"),
            StoryParagraph("He had never seen them, never heard them, never known them.", "هرگز ندیده بودشان، هرگز نشنیده بودشان، هرگز نشناخته بودشان."),
            StoryParagraph("And yet, here he was, about to die, condemned by a court he had never seen, sentenced by a judge he had never met.", "و با این حال، اینجا بود، در شرف مرگ، محکوم توسط دادگاهی که هرگز ندیده بود، حکم‌شده توسط قاضی‌ای که هرگز ملاقات نکرده بود."),
            StoryParagraph("The two men took hold of K., and they led him to a stone, and they made him kneel.", "دو مرد ک. را گرفتند و به سنگی بردند و به زانو درش آوردند."),
            StoryParagraph("One of them took out a knife, a long, sharp butcher's knife, and he held it up.", "یکی از آن‌ها چاقویی بیرون آورد، چاقوی قصابی بلند و تیز و بالا گرفت."),
            StoryParagraph("'Do you have anything to say?' the man asked.", "مرد پرسید: «چیزی برای گفتن داری؟»"),
            StoryParagraph("K. thought about his life, about his trial, about everything that had happened.", "ک. به زندگی‌اش فکر کرد، به محاکمه‌اش، به هر چیزی که اتفاق افتاده بود."),
            StoryParagraph("He thought about the absurdity of it all, about the meaninglessness, about the injustice.", "به پوچی همه‌اش فکر کرد، به بی‌معنایی، به بی‌عدالتی."),
            StoryParagraph("And he thought about what he had learned, about what he had become, about what he had lost.", "و به آنچه آموخته بود فکر کرد، به آنچه شده بود، به آنچه از دست داده بود."),
            StoryParagraph("He had lost everything: his position, his reputation, his friends, his future.", "همه چیز از دست داده بود: مقامش، آبرویش، دوستانش، آینده‌اش."),
            StoryParagraph("But he had gained something too: a knowledge, a wisdom, a truth that he would never have found in his old, comfortable life.", "اما چیزی هم به دست آورده بود: دانشی، خردی، حقیقتی که هرگز در زندگی راحت قدیمی‌اش نمی‌یافت."),
            StoryParagraph("He had learned that the world is absurd, that justice is impossible, that meaning is a human creation.", "آموخته بود جهان پوچ است، عدالت ناممکن، معنا ساخته انسان."),
            StoryParagraph("He had learned that we are alone, that we are responsible, that we must live without hope of reward.", "آموخته بود تنهاییم، مسئولیم، باید بدون امید به پاداش زندگی کنیم."),
            StoryParagraph("And in that learning, in that acceptance, in that despair that was also a kind of peace, K. found something like freedom.", "و در آن آموختن، در آن پذیرش، در آن ناامیدی که نوعی آرامش هم بود، ک. چیزی شبیه آزادی یافت."),
            StoryParagraph("'I have nothing to say,' he said, at last. 'Except that I accept.'", "سرانجام گفت: «چیزی برای گفتن ندارم. جز اینکه می‌پذیرم.»"),
            StoryParagraph("The man nodded, and he brought the knife down, and K. died.", "مرد سر تکان داد و چاقو را پایین آورد و ک. مرد."),
            StoryParagraph("'Like a dog!' he thought, as the darkness closed in around him. 'Like a dog!'", "فکر کرد: «مثل سگی!» در حالی که تاریکی دورش بسته می‌شد. «مثل سگی!»"),
            StoryParagraph("And that was the end of Josef K., and the end of his trial, and the end of everything he had been.", "و این پایان یوزف ک. بود و پایان محاکمه‌اش و پایان هر چیزی که بوده بود."),
            StoryParagraph("But the court continued; the court always continues; the court will continue until the end of time.", "اما دادگاه ادامه یافت؛ دادگاه همیشه ادامه می‌یابد؛ دادگاه تا پایان زمان ادامه می‌یابد."),
            StoryParagraph("For the court is not a place or a time; it is a condition, a state of being, the human condition itself.", "زیرا دادگاه نه مکان است و نه زمان؛ وضعیتی است، حالتی از بودن، خودِ وضعیت بشری."),
            StoryParagraph("And we are all on trial, all the time, before a court we cannot see, accused of crimes we do not know.", "و همه‌مان در محاکمه‌ایم، همیشه، در برابر دادگاهی که نمی‌بینیم، متهم به جنایاتی که نمی‌دانیم."),
            StoryParagraph("And some of us, like K., learn to accept it; and some of us never do.", "و برخی از ما، مثل ک.، یاد می‌گیریم بپذیریم؛ و برخی از ما هرگز."),
            StoryParagraph("But whether we accept or not, the court continues, and the trial goes on, and the sentence will be carried out.", "اما چه بپذیریم چه نپذیریم، دادگاه ادامه می‌یابد و محاکمه جریان دارد و حکم اجرا می‌شود."),
            StoryParagraph("And all we can do is live, and try to be honest, and hope that we are not condemned for crimes we did not commit.", "و تنها کاری که می‌توانیم بکنیم زندگی کردن است و تلاش برای صادق بودن و امید به اینکه برای جنایاتی که مرتکب نشده‌ایم محکوم نشویم.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("The Trial, written by Franz Kafka between 1914 and 1915, is one of the most disturbing and influential novels of the twentieth century.", "محاکمه، نوشته فرانتس کافکا بین ۱۹۱۴ و ۱۹۱۵، یکی از آشفته‌کننده‌ترین و تأثیرگذارترین رمان‌های قرن بیستم است."),
            StoryParagraph("It tells the story of Josef K., a respectable bank clerk who is arrested one morning without being told what crime he has committed.", "داستان یوزف ک. را تعریف می‌کند، کارمند بانک محترمی که یک صبح بدون آنکه به او گفته شود چه جنایتی کرده دستگیر می‌شود."),
            StoryParagraph("K. spends the rest of the novel trying to understand his situation, to defend himself, to find justice.", "ک. باقی رمان را صرف تلاش برای فهمیدن موقعیتش می‌کند، برای دفاع از خودش، برای یافتن عدالت."),
            StoryParagraph("But he never learns what he is accused of, never meets his accusers, never sees the court that will judge him.", "اما هرگز نمی‌فهمد متهم به چیست، هرگز متهمانش را ملاقات نمی‌کند، هرگز دادگاهی که داوری‌اش می‌کند را نمی‌بیند."),
            StoryParagraph("He is convicted, and executed, without ever knowing why.", "او محکوم می‌شود و اعدام می‌شود، بدون آنکه هرگز بداند چرا."),
            StoryParagraph("The novel is a parable of the human condition, a vision of life as an incomprehensible trial.", "رمان مَثَلی از وضعیت بشری است، بینشی از زندگی به‌عنوان محاکمه‌ای غیرقابل فهم."),
            StoryParagraph("We are all, Kafka suggests, on trial, accused of crimes we do not know, before a court we cannot see.", "کافکا پیشنهاد می‌دهد همه‌مان در محاکمه‌ایم، متهم به جنایاتی که نمی‌دانیم، در برابر دادگاهی که نمی‌بینیم."),
            StoryParagraph("We spend our lives trying to understand our situation, to defend ourselves, to find justice; but the court is indifferent, and the trial continues, and the sentence is carried out.", "عمرمان را صرف تلاش برای فهمیدن موقعیتمان می‌کنیم، برای دفاع از خودمان، برای یافتن عدالت؛ اما دادگاه بی‌تفاوت است و محاکمه ادامه می‌یابد و حکم اجرا می‌شود."),
            StoryParagraph("The novel has been interpreted in many ways; some see it as a critique of bureaucracy, others as a religious allegory, others as a philosophical meditation on the nature of existence.", "رمان به شیوه‌های بسیاری تفسیر شده؛ برخی آن را نقد بوروکراسی می‌بینند، برخی همچون تمثیلی دینی، برخی همچون مراقبه‌ای فلسفی درباره ماهیت وجود."),
            StoryParagraph("But perhaps the most powerful interpretation is the existential one: that the novel is about the absurdity of human existence, about the impossibility of finding meaning in a meaningless world.", "اما شاید قوی‌ترین تفسیر همان وجودی است: که رمان درباره پوچی وجود انسانی است، درباره ناممکن بودن یافتن معنا در جهانی بی‌معنا."),
            StoryParagraph("K. is not guilty of any crime, in the ordinary sense; but he is guilty in the sense that all human beings are guilty.", "ک. به هیچ جنایتی گناهکار نیست، به معنای معمولی؛ اما به این معنا گناهکار است که همه انسان‌ها گناهکارند."),
            StoryParagraph("He is guilty of being human, of being finite, of being caught in a world he cannot understand or control.", "گناهکار است که انسان است، که متناهی است، که در جهانی گرفتار است که نمی‌تواند بفهمد یا کنترل کند."),
            StoryParagraph("And the court is not a court of law; it is the universe itself, the vast, indifferent, incomprehensible universe in which we live.", "و دادگاه دادگاه قانون نیست؛ خودِ جهان است، جهان عظیم، بی‌تفاوت، غیرقابل فهمی که در آن زندگی می‌کنیم."),
            StoryParagraph("K.'s trial is the trial of every human being, the trial of existence itself; and his death is the death that awaits us all.", "محاکمه ک. محاکمه هر انسانی است، محاکمه خود وجود؛ و مرگش همان مرگی است که همه‌مان را انتظار می‌کشد."),
            StoryParagraph("The novel ends with K.'s execution, which is also a kind of resolution; for in dying, K. finally accepts what he has been unable to accept in life.", "رمان با اعدام ک. پایان می‌یابد، که نوعی حل شدن هم هست؛ زیرا در مردن، ک. سرانجام می‌پذیرد آنچه در زندگی نتوانسته بود بپذیرد."),
            StoryParagraph("He accepts that the trial is meaningless, that the court is unjust, that life is absurd.", "می‌پذیرد که محاکمه بی‌معناست، که دادگاه بی‌عدالت است، که زندگی پوچ است."),
            StoryParagraph("And in that acceptance, he finds a kind of peace, a peace that is also a despair, a peace that is also a freedom.", "و در آن پذیرش، نوعی آرامش می‌یابد، آرامشی که ناامیدی هم هست، آرامشی که آزادی هم هست."),
            StoryParagraph("For the only freedom available to us, Kafka suggests, is the freedom to accept what we cannot change.", "زیرا تنها آزادی‌ای که برای ما در دسترس است، کافکا پیشنهاد می‌دهد، آزادی پذیرش آنچه نمی‌توانیم تغییرش دهیم."),
            StoryParagraph("The only wisdom is the wisdom of accepting the absurd, of living without hope, of facing the meaningless with courage and dignity.", "تنها خرد، خرد پذیرش پوچی است، زندگی بدون امید، رویارویی با بی‌معنا با شجاعت و وقار."),
            StoryParagraph("K. dies like a dog, as he says; but he dies with a kind of dignity, a kind of acceptance, a kind of peace.", "ک. مثل سگی می‌میرد، همانطور که خودش می‌گوید؛ اما با نوعی وقار می‌میرد، نوعی پذیرش، نوعی آرامش."),
            StoryParagraph("And that, perhaps, is the best we can hope for: not to escape the trial, not to win the case, but to face it with honesty and courage.", "و این، شاید، بهترین چیزی است که می‌توانیم امیدوار باشیم: نه فرار از محاکمه، نه بردن پرونده، بلکه رویارویی با آن با صداقت و شجاعت."),
            StoryParagraph("The Trial is not a comforting novel; it offers no solutions, no answers, no hope.", "محاکمه رمانی دلگرم‌کننده نیست؛ راه‌حلی ارائه نمی‌دهد، پاسخی، امیدی."),
            StoryParagraph("But it is an honest novel, a true novel, a novel that shows us the world as it is, not as we wish it were.", "اما رمانی صادق است، رمانی راستین، رمانی که جهان را آن‌گونه که هست به ما نشان می‌دهد، نه آن‌گونه که آرزو داریم باشد."),
            StoryParagraph("And in its honesty, in its truth, in its unflinching vision of the human condition, it offers something more valuable than comfort: it offers understanding.", "و در صداقتش، در راستین بودنش، در بینش بی‌لرزشش از وضعیت بشری، چیزی ارزشمندتر از تسلی ارائه می‌دهد: فهم."),
            StoryParagraph("Understanding of what it means to be human, to be caught in a world we cannot control, to face a fate we cannot understand.", "فهم اینکه انسان بودن یعنی چه، گرفتار بودن در جهانی که نمی‌توانیم کنترلش کنیم، رویارویی با سرنوشتی که نمی‌توانیم بفهمیم."),
            StoryParagraph("And that understanding, however painful, is better than any illusion.", "و آن فهم، هر چقدر دردناک، از هر توهمی بهتر است."),
            StoryParagraph("For the truth, as the priest tells K., is better than a comfortable lie; and the trial, however terrible, is better than the ignorance in which most of us live.", "زیرا حقیقت، همانطور که کشیش به ک. می‌گوید، از دروغی راحت بهتر است؛ و محاکمه، هر چقدر هولناک، از نادانی‌ای که بیشترمان در آن زندگی می‌کنیم بهتر است."),
            StoryParagraph("Kafka wrote The Trial during a time of great personal turmoil; he was engaged, then disengaged, then engaged again; he was working in a bureaucratic job he hated; he was torn between his art and his obligations.", "کافکا محاکمه را در زمانی از آشوب شخصی بزرگ نوشت؛ نامزد کرده بود، بعد جدا، بعد دوباره نامزد؛ در شغلی بوروکراتیک که از آن متنفر بود کار می‌کرد؛ بین هنرش و تعهداتش پاره شده بود."),
            StoryParagraph("The novel reflects his own struggles, his own sense of being trapped, his own feeling of being judged by forces he could not understand.", "رمان مبارزات خودش را بازتاب می‌دهد، حس خودش از گرفتار بودن، احساس خودش از داوری شدن توسط نیروهایی که نمی‌توانست بفهمد."),
            StoryParagraph("And it is this personal element, this authentic despair, that gives the novel its power.", "و این عنصر شخصی است، این ناامیدی اصیل، که به رمان قدرتش را می‌دهد."),
            StoryParagraph("For Kafka was not writing about a fictional Josef K.; he was writing about himself, about his own trial, about his own struggle to find meaning in a meaningless world.", "زیرا کافکا درباره یوزف ک. خیالی نمی‌نوشت؛ درباره خودش می‌نوشت، درباره محاکمه خودش، درباره مبارزه خودش برای یافتن معنا در جهانی بی‌معنا."),
            StoryParagraph("And because he wrote about himself, he wrote about all of us; because he told his own truth, he told the truth of the human condition.", "و چون درباره خودش نوشت، درباره همه‌مان نوشت؛ چون حقیقت خودش را گفت، حقیقت وضعیت بشری را گفت."),
            StoryParagraph("The Trial is not a novel to be enjoyed; it is a novel to be endured, to be suffered, to be lived.", "محاکمه رمانی نیست که لذت برده شود؛ رمانی است که تحمل شود، رنج کشیده شود، زندگی شود."),
            StoryParagraph("But it is a novel that, once read, cannot be forgotten; that, once understood, changes the reader; that, once lived, becomes part of who we are.", "اما رمانی است که یک بار خوانده شده، فراموش نمی‌شود؛ یک بار فهمیده شده، خواننده را تغییر می‌دهد؛ یک بار زیسته شده، بخشی از آنچه هستیم می‌شود."),
            StoryParagraph("And that is the mark of great literature: not that it entertains, but that it transforms.", "و این نشانه ادبیات بزرگ است: نه اینکه سرگرم می‌کند، بلکه اینکه دگرگون می‌کند."),
            StoryParagraph("And so the trial of Josef K. ends, but the trial of every reader begins; for we too are on trial, and we too must face the court, and we too must die.", "و اینگونه محاکمه یوزف ک. پایان می‌یابد، اما محاکمه هر خواننده آغاز می‌شود؛ زیرا ما هم در محاکمه‌ایم و ما هم باید با دادگاه روبرو شویم و ما هم باید بمیریم."),
            StoryParagraph("The only question is how we will face it: with courage or with fear, with honesty or with illusion, with acceptance or with despair.", "تنها پرسش این است که چگونه با آن روبرو می‌شویم: با شجاعت یا با ترس، با صداقت یا با توهم، با پذیرش یا با ناامیدی."),
            StoryParagraph("And that question, Kafka suggests, is the only question that matters.", "و آن پرسش، کافکا پیشنهاد می‌دهد، تنها پرسشی است که اهمیت دارد."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز.")
        )
    )
}